// Which syllable type each state accepts, if any.
pub(crate) static INDIC_ACCEPTS: [u8; 107] = [
    5, 4, 0, 1, 5, 5, 4, 5, 5, 5, 2, 0, 5, 5, 4, 3, 4, 0, 0, NONE, 0, 0, 0, 0, 0, 1, NONE, NONE, 1, 1, 1, 1, NONE, 5, 5,
    5, 5, 5, 5, 5, 5, 2, 2, NONE, 2, 2, 2, 2, 2, 0, 3, NONE, 3, 3, 3, 0, 0, 0, 0, 0, NONE, 0, NONE, 0, 0, 0, 0, 0, 1, 1,
    1, NONE, 1, 1, 1, 1, 1, NONE, 5, 2, NONE, 2, 2, 2, 2, NONE, 2, 2, 2, 2, 2, 0, 0, 0, 3, 3, 3, 3, NONE, 0, 0, 1, NONE,
    1, 1, NONE, 2,
];

pub(crate) fn indic_accept(state: u8) -> Option<IndicSyllable> {
    IndicSyllable::from_index(*INDIC_ACCEPTS.get(state as usize)?)
}

// `khmer` syllable types, in the grammar's own order.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
#[allow(clippy::enum_variant_names)]
pub(crate) enum KhmerSyllable {
    ConsonantSyllable,
    NonKhmerCluster,
    BrokenCluster,
}

impl KhmerSyllable {
    fn from_index(i: u8) -> Option<Self> {
        Some(match i {
            0 => KhmerSyllable::ConsonantSyllable,
            1 => KhmerSyllable::NonKhmerCluster,
            2 => KhmerSyllable::BrokenCluster,
            _ => return None,
        })
    }
}

impl From<KhmerSyllable> for u8 {
    fn from(s: KhmerSyllable) -> u8 {
        match s {
            KhmerSyllable::ConsonantSyllable => 0,
            KhmerSyllable::NonKhmerCluster => 1,
            KhmerSyllable::BrokenCluster => 2,
        }
    }
}

