// `myanmar` syllable types, in the grammar's own order.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
#[allow(clippy::enum_variant_names)]
pub(crate) enum MyanmarSyllable {
    ConsonantSyllable,
    NonMyanmarCluster,
    BrokenCluster,
}

impl MyanmarSyllable {
    fn from_index(i: u8) -> Option<Self> {
        Some(match i {
            0 => MyanmarSyllable::ConsonantSyllable,
            1 => MyanmarSyllable::NonMyanmarCluster,
            2 => MyanmarSyllable::BrokenCluster,
            _ => return None,
        })
    }
}

impl From<MyanmarSyllable> for u8 {
    fn from(s: MyanmarSyllable) -> u8 {
        match s {
            MyanmarSyllable::ConsonantSyllable => 0,
            MyanmarSyllable::NonMyanmarCluster => 1,
            MyanmarSyllable::BrokenCluster => 2,
        }
    }
}

